package com.codearena.service;
import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.client.RestTemplate;
import java.util.*;import java.util.regex.*;
@Service public class Judge0ExecutionService {
 private final RestTemplate http=new RestTemplate(); private final ObjectMapper mapper=new ObjectMapper(); private final String base;
 public Judge0ExecutionService(@Value("${judge0.url}")String base){this.base=base.replaceAll("/$","");}
 private static final Map<String,Integer> IDS=Map.of("javascript",63,"python",71,"java",62,"cpp",54,"c",50,"go",60,"rust",73);
 public Integer languageId(String language){return IDS.get(language);}
 public Map<String,Object> submit(String source,int languageId)throws Exception{HttpHeaders h=new HttpHeaders();h.setContentType(MediaType.APPLICATION_JSON);Map<String,Object>b=new LinkedHashMap<>();b.put("source_code",source);b.put("language_id",languageId);b.put("stdin","");b.put("cpu_time_limit",5);b.put("memory_limit",256000);ResponseEntity<Map>r=http.postForEntity(base+"/submissions?base64_encoded=false&wait=false",new HttpEntity<>(b,h),Map.class);if(!r.getStatusCode().is2xxSuccessful()||r.getBody()==null||r.getBody().get("token")==null)throw new RuntimeException("Judge0 submit failed: "+r.getStatusCode().value());String token=(String)r.getBody().get("token");for(int i=0;i<16;i++){Thread.sleep(800);Map<?,?>result=http.getForObject(base+"/submissions/"+token+"?base64_encoded=false",Map.class);if(result!=null){Object status=result.get("status");int id=status instanceof Map&&((Map<?,?>)status).get("id") instanceof Number?((Number)((Map<?,?>)status).get("id")).intValue():1;if(id>2)return (Map<String,Object>)result;}}throw new RuntimeException("Execution timeout");}
 public List<Object> parseJsonArray(String s){try{return mapper.readValue(s,List.class);}catch(Exception e){return List.of();}}
 public static String normalizeOutput(String raw){return raw==null?"":raw.trim().replaceAll("\\s*,\\s*",",").replaceAll("\\[\\s+","[").replaceAll("\\s+\\]","]").toLowerCase().replaceAll("^\"(.*)\"$","$1");}
 public String buildRunnableCode(String code,String language,String input,String expected){List<Object>args=parseArgs(input);String fn=extractFunction(code,language);if(fn==null)return code;String call=args.stream().map(a->serialize(a,language)).reduce((a,b)->a+", "+b).orElse("");if("javascript".equals(language))return code+"\ntry{const result="+fn+"("+call+");console.log(Array.isArray(result)?JSON.stringify(result):String(result));}catch(e){console.error(e.message);process.exit(1)}";
 if("python".equals(language)){return code+"\ntry:\n result="+fn+"("+call+")\n import json\n print(json.dumps(result,separators=(',', ':')).lower() if isinstance(result,list) else str(result).lower() if isinstance(result,bool) else result)\nexcept Exception as e:\n import sys\n print(str(e),file=sys.stderr)\n sys.exit(1)";}
 if("java".equals(language)){String clean=code.replaceAll("public\\s+class\\s+\\w+","static class Solution");String callLine="System.out.println(sol."+fn+"("+call+"));";return "import java.util.*;"+System.lineSeparator()+"public class Main{"+System.lineSeparator()+clean+System.lineSeparator()+"public static void main(String[] a){try{Solution sol=new Solution();"+callLine+"}catch(Exception e){System.err.println(e.getMessage());}}}";}
 if("cpp".equals(language))return "#include <bits/stdc++.h>\nusing namespace std;\n"+code+"\nint main(){try{Solution sol;auto r=sol."+fn+"("+call+");cout<<r<<endl;}catch(...){cerr<<\"Runtime error\"<<endl;}}";
 return code;}
 private String extractFunction(String code,String language){Pattern p=null;if(language.equals("javascript"))p=Pattern.compile("(?:function\\s+(\\w+)\\s*\\(|(?:const|let|var)\\s+(\\w+)\\s*=\\s*(?:function|\\())");else if(language.equals("python"))p=Pattern.compile("def\\s+(\\w+)\\s*\\(");else if(language.equals("java"))p=Pattern.compile("public\\s+(?:static\\s+)?(?:[\\w<>\\[\\]]+)\\s+(\\w+)\\s*\\(");else if(language.equals("cpp"))p=Pattern.compile("[\\w<>:*&\\[\\]]+\\s+(\\w+)\\s*\\(");if(p==null)return null;Matcher m=p.matcher(code);if(!m.find())return null;return m.group(1)!=null?m.group(1):m.groupCount()>1&&m.group(2)!=null?m.group(2):null;}
 private List<Object>parseArgs(String input){List<Object>out=new ArrayList<>();if(input==null||input.isBlank())return out;Matcher m=Pattern.compile("\\w+\\s*=\\s*(\\[[\\s\\S]*?\\]|\"[^\"]*\"|'[^']*'|-?\\d+(?:\\.\\d+)?|true|false)").matcher(input);while(m.find()){String v=m.group(1);try{out.add(mapper.readValue(v,Object.class));}catch(Exception e){out.add(v.replaceAll("^[\"']|[\"']$",""));}}if(out.isEmpty()){try{out.add(mapper.readValue(input,Object.class));}catch(Exception e){out.add(input);}}return out;}
 private String serialize(Object v,String language){if(v instanceof String)return "\""+v+"\"";if(v instanceof Boolean){boolean value=(Boolean)v;return language.equals("python")?(value?"True":"False"):v.toString();}if(v instanceof List<?> list){String inner=list.stream().map(x->serialize(x,language)).reduce((a,b)->a+", "+b).orElse("");if(language.equals("python")||language.equals("javascript")||language.equals("go")||language.equals("rust"))return "["+inner+"]";if(language.equals("java")||language.equals("cpp")){if(list.isEmpty())return language.equals("java")?"new int[]{}":"{}";Object first=list.get(0);if(language.equals("java"))return (first instanceof String?"new String[]{":"new int[]{")+inner+"}";if(language.equals("cpp"))return (first instanceof String?"vector<string>{":"vector<int>{")+inner+"}";}return "{}";}return String.valueOf(v);}
}
